#include <stdio.h>
#include <stdbool.h>

int main() {
    int limit = 20000;
    bool is_prime[limit];

    // Initialize all entries as true
    for (int i = 0; i < limit; i++) {
        is_prime[i] = true;
    }

    // Sieve of Eratosthenes
    for (int p = 2; p * p < limit; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i < limit; i += p) {
                is_prime[i] = false;
            }
        }
    }

    int sum = 0;
    for (int p = 2; p < limit; p++) {
        if (is_prime[p]) {
            sum += p;
        }
    }

    printf("%d\n", sum);

    return 0;
}

