#include <stdio.h>
#include <stdlib.h>

int main() {
    // Use an array to store digits in reverse order (least significant first)
    // 2^100 is approximately 1.26765e+30, so we need about 31 digits.
    // We'll use a safe size of 100.
    int digits[100];
    int size = 0;

    // Function to multiply the large number represented by 'digits' by a scalar 'factor'
    // Returns the new size.
    int multiply(int *digits, int size, int factor) {
        int carry = 0;
        for (int i = 0; i < size; i++) {
            long long current = (long long)digits[i] * factor + carry;
            digits[i] = (int)(current % 10);
            carry = (int)(current / 10);
        }
        while (carry) {
            digits[size++] = carry % 10;
            carry /= 10;
        }
        return size;
    }

    // Initialize the number to 1 (represented as a single digit)
    digits[0] = 1;
    size = 1;

    // Compute 2^100 by multiplying by 2, 100 times
    for (int i = 0; i < 100; i++) {
        size = multiply(digits, size, 2);
    }

    // Compute the sum of the decimal digits
    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += digits[i];
    }

    // Print the final integer answer
    printf("%d\n", sum);

    return 0;
}

