typedef long long ll;

ll power(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp /= 2;
    }
    return result;
}

int main() {
    ll base = 3;
    ll exp = 1000000000LL;
    ll mod = 1000000007LL;
    printf("%lld\n", power(base, exp, mod));
    return 0;
}

