#include <stdio.h>
#include <stdlib.h>

int main() {
    int x[51];
    int i;

    // Initialize x0
    x[0] = 42;

    // Generate x1 to x51
    // Formula: x(k+1) = (1103515245 * x(k) + 12345) mod 2^31
    // Note: 2^31 is 2147483648. Since we are using signed 32-bit int, 
    // the result of the multiplication might overflow before modulo.
    // We can use unsigned int for the calculation to handle the large intermediate value correctly.
    unsigned int multiplier = 1103515245U;
    unsigned int adder = 12345U;
    unsigned int modulus = 2147483648U; // 2^31

    for (i = 1; i <= 51; i++) {
        unsigned int temp = (unsigned int)((long long)x[i-1] * multiplier + adder);
        x[i] = (int)(temp % modulus);
    }

    // Sort the array x[0] to x[50] (51 elements)
    // We need the 26th smallest, which is at index 25 (0-based) after sorting.
    for (i = 0; i < 51; i++) {
        for (int j = i + 1; j < 51; j++) {
            if (x[i] > x[j]) {
                int temp_val = x[i];
                x[i] = x[j];
                x[j] = temp_val;
            }
        }
    }

    // The median of 51 elements is the 26th smallest (index 25)
    printf("%d\n", x[25]);

    return 0;
}

