#include <stdio.h>
#include <stdbool.h>

// Function to check if a number is a palindrome in base 10
bool is_palindrome_base10(int n) {
    int original = n;
    int reversed = 0;
    while (n > 0) {
        reversed = reversed * 10 + n % 10;
        n /= 10;
    }
    return original == reversed;
}

// Function to check if a number is a palindrome in base 2
bool is_palindrome_base2(int n) {
    if (n == 0) return true;
    int original = n;
    int reversed = 0;
    while (n > 0) {
        reversed = (reversed << 1) | (n & 1);
        n >>= 1;
    }
    return original == reversed;
}

int main() {
    int sum = 0;
    for (int n = 1; n < 300000; n++) {
        if (is_palindrome_base10(n) && is_palindrome_base2(n)) {
            sum += n;
        }
    }
    printf("%d\n", sum);
    return 0;
}

