#include <stdio.h>

int main() {
    int n = 16;
    // The number of steps right is n, and the number of steps down is n.
    // Total steps = 2n. We need to choose n steps to be 'right' (or 'down').
    // Formula: C(2n, n) = (2n)! / (n! * n!)

    // We compute C(32, 16) using a loop to avoid overflow with large factorials
    // by multiplying and dividing incrementally.
    // C(n, k) = C(n, k-1) * (n - k + 1) / k

    int total_steps = 2 * n;
    int steps_right = n;
    unsigned long long result = 1;

    for (int i = 1; i <= steps_right; i++) {
        result = result * (total_steps - i + 1);
        result = result / i;
    }

    printf("%lu\n", result);

    return 0;
}
